    // ══════════════════════════════════════════════════════════════
    // AI SPEND — what this pipeline actually costs
    //
    // The estimation tab beside this one prices a live-action shoot: day rates,
    // catering, grip, a 10% contingency. This film has no crew. What it spends
    // is tokens at Anthropic, credits at Meshy and Runway, characters and
    // seconds at ElevenLabs — measured at the moment of every provider call by
    // lib/usage-meter.js, with nothing to enter by hand.
    //
    // Dollars AND native units are shown side by side throughout, because they
    // are different questions. Dollars are what the film cost; credits are what
    // runs out mid-render on a Tuesday.
    // ══════════════════════════════════════════════════════════════

    const CAP_COLOR = {
        image: '#2196f3', video: '#9c27b0', voice: '#ff9800', music: '#4caf50',
        sfx: '#00bcd4', ambient: '#009688', llm: '#e91e63', model3d: '#795548',
        lipsync: '#3f51b5', post: '#607d8b',
    };
    const capColor = c => CAP_COLOR[c] || '#9e9e9e';
    const qty = n => {
        const v = Number(n) || 0;
        if (v >= 1000000) return (v / 1000000).toFixed(2) + 'M';
        if (v >= 1000) return (v / 1000).toFixed(1) + 'k';
        return Number.isInteger(v) ? String(v) : v.toFixed(2);
    };

    let currentSpend = null;

    async function loadSpend() {
        if (!state.currentProject) return;
        setStatus('Loading spend...');
        try {
            const s = await api('/projects/' + state.currentProject.id + '/spend');
            currentSpend = s;
            renderSpendBackfill(s);
            renderSpendHeadline(s);
            renderSpendUnits(s);
            await renderSubscription();
            renderSpendByCapability(s);
            renderSpendOverTime(s);
            renderSpendByModel(s);
            renderSpendByShot(s);
            document.getElementById('spendNote').textContent = s.note || '';
            setStatus('Spend loaded');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // A project generated before metering existed has real spend and reports
    // zero — which looks identical to a project that generated nothing. Say so,
    // and offer the reconstruction rather than leaving the zero to be believed.
    function renderSpendBackfill(s) {
        const el = document.getElementById('spendBackfillBanner');
        if (!s.backfill_available) { el.innerHTML = ''; return; }
        el.innerHTML = `
            <div class="card" style="border-left:3px solid var(--gl-warning);">
                <strong>${s.untracked_assets} asset(s) were generated before spend tracking existed.</strong>
                <p class="text-sm text-muted" style="margin:4px 0 8px;">Their cost can be reconstructed by pricing what is on record — every keyframe, plate and clip is one generation someone paid for. It is a <em>floor</em>: generations that failed cost money and left nothing behind. Reconstructed spend is flagged as an estimate and counted separately.</p>
                <button class="btn btn-secondary btn-sm" onclick="previewBackfill()">Preview</button>
                <button class="btn btn-primary btn-sm" onclick="runBackfill()" style="margin-left:6px;">Reconstruct</button>
            </div>`;
    }

    async function previewBackfill() {
        try {
            const r = await api('/projects/' + state.currentProject.id + '/spend/backfill',
                { method: 'POST', body: JSON.stringify({ dry_run: true }) });
            alert(`${r.recorded} generation(s) would be reconstructed at ${money(r.total_usd)}.\n\n` +
                  `${r.skipped} asset(s) skipped (not produced by a paid provider).\n\n${r.caveat}`);
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function runBackfill() {
        try {
            const r = await api('/projects/' + state.currentProject.id + '/spend/backfill',
                { method: 'POST', body: JSON.stringify({}) });
            setStatus(`Reconstructed ${r.recorded} generation(s) — ${money(r.total_usd)}`);
            loadSpend();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function renderSpendHeadline(s) {
        const limit = s.budget_limit || 0;
        const pct = s.budget_used_pct;
        const barColor = pct > 90 ? 'var(--gl-error)' : pct > 70 ? 'var(--gl-warning)' : 'var(--gl-success)';
        const perMin = s.usd_per_minute || 0;

        document.getElementById('spendHeadline').innerHTML = `
            <div class="card">
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;">
                    ${statTile('Total spent', money(s.total_usd), `${s.call_count} provider call(s)`)}
                    ${statTile('Per minute of footage', perMin > 0 ? money(perMin) : '—',
                        s.footage_seconds > 0 ? `over ${(s.footage_seconds / 60).toFixed(1)} min of shots` : 'no shot durations yet')}
                    ${statTile('Per shot', s.shot_count > 0 ? money(s.usd_per_shot) : '—', `${s.shot_count} shot(s)`)}
                    ${statTile('Budget', limit > 0 ? money(limit) : 'Not set',
                        limit > 0 ? money(s.remaining) + ' remaining' : 'no ceiling — runs are never refused')}
                </div>
                ${limit > 0 ? `
                    <div style="background:var(--gl-border-subtle);border-radius:4px;height:8px;overflow:hidden;margin-top:14px;">
                        <div style="background:${barColor};height:100%;width:${Math.min(100, pct)}%;border-radius:4px;transition:width .3s;"></div>
                    </div>
                    <p class="text-sm text-muted" style="margin-top:4px;">${pct}% of budget used</p>` : ''}
                ${s.estimated_usd > 0 ? `
                    <p class="text-sm text-muted" style="margin-top:10px;border-top:1px solid var(--gl-border-subtle);padding-top:8px;">
                        ${money(s.measured_usd)} measured from live calls &middot;
                        ${money(s.estimated_usd)} reconstructed from ${s.estimated_calls} earlier generation(s).
                        Reconstructed spend is a floor.
                    </p>` : ''}
            </div>`;
    }

    function statTile(label, value, sub) {
        return `<div>
            <div class="text-sm text-muted">${esc(label)}</div>
            <div style="font-size:24px;font-weight:600;line-height:1.2;">${esc(value)}</div>
            <div class="text-sm text-muted">${esc(sub || '')}</div>
        </div>`;
    }

    // Credits and tokens, per provider. This is the number a prepaid balance
    // runs out of, and a dollars-only report hides it completely.
    function renderSpendUnits(s) {
        const rows = s.by_provider || [];
        const el = document.getElementById('spendUnits');
        if (!rows.length) { el.innerHTML = ''; return; }
        el.innerHTML = `
            <h3 class="mb-8">Provider usage</h3>
            <div class="card">
                <table class="render-table" style="width:100%;">
                    <tr><th>Provider</th><th style="text-align:right;">Consumed</th><th style="text-align:right;">Calls</th><th style="text-align:right;">Cost</th></tr>
                    ${rows.map(r => `<tr>
                        <td><span class="badge">${esc(r.provider)}</span></td>
                        <td style="text-align:right;">${r.native_quantity > 0 ? qty(r.native_quantity) + ' ' + esc(r.native_unit) + (r.native_quantity === 1 ? '' : 's') : '—'}</td>
                        <td style="text-align:right;">${r.calls}</td>
                        <td style="text-align:right;">${r.usd > 0 ? money(r.usd) : '<span class="text-muted">self-hosted</span>'}</td>
                    </tr>`).join('')}
                </table>
            </div>`;
    }

    function renderSpendByCapability(s) {
        const entries = Object.entries(s.by_capability || {});
        const el = document.getElementById('spendByCapability');
        if (!entries.length) {
            el.innerHTML = '<div class="card"><p class="text-sm text-muted">No provider calls recorded yet. Spend appears here automatically the moment anything is generated.</p></div>';
            return;
        }
        const max = Math.max(...entries.map(([, v]) => v.usd), 0.0001);
        el.innerHTML = `
            <h3 class="mb-8">Where the money went</h3>
            <div class="card">
                ${entries.map(([cap, v]) => `
                    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
                        <span class="text-sm" style="width:90px;flex-shrink:0;">${esc(cap)}</span>
                        <div style="flex:1;background:var(--gl-border-subtle);border-radius:3px;height:16px;overflow:hidden;">
                            <div style="background:${capColor(cap)};height:100%;width:${(v.usd / max * 100)}%;border-radius:3px;"></div>
                        </div>
                        <span class="text-sm" style="width:70px;text-align:right;">${money(v.usd)}</span>
                        <span class="text-sm text-muted" style="width:110px;text-align:right;">${v.calls}× &middot; ${v.native_quantity > 0 ? qty(v.native_quantity) + ' ' + esc(v.native_unit) : '—'}</span>
                    </div>`).join('')}
            </div>`;
    }

    // Cumulative, not per-day. The question this answers is "how fast is this
    // film getting expensive", and a daily bar chart with gaps hides the slope.
    function renderSpendOverTime(s) {
        const days = s.by_day || [];
        const el = document.getElementById('spendOverTime');
        if (days.length < 2) { el.innerHTML = ''; return; }

        const W = 640, H = 120, PAD = 4;
        let running = 0;
        const points = days.map((d, i) => {
            running += d.usd;
            return { x: (i / (days.length - 1)) * (W - PAD * 2) + PAD, y: running, day: d.day, daily: d.usd };
        });
        const maxY = Math.max(...points.map(p => p.y), 0.0001);
        const scaled = points.map(p => `${p.x.toFixed(1)},${(H - PAD - (p.y / maxY) * (H - PAD * 2)).toFixed(1)}`);
        const area = `${PAD},${H - PAD} ${scaled.join(' ')} ${(W - PAD)},${H - PAD}`;

        el.innerHTML = `
            <h3 class="mb-8">Spend over time</h3>
            <div class="card">
                <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px;display:block;" preserveAspectRatio="none">
                    <polygon points="${area}" fill="var(--gl-accent, #2196f3)" opacity="0.15"></polygon>
                    <polyline points="${scaled.join(' ')}" fill="none" stroke="var(--gl-accent, #2196f3)" stroke-width="2"></polyline>
                </svg>
                <div class="flex-between text-sm text-muted" style="margin-top:4px;">
                    <span>${esc(days[0].day)}</span>
                    <span>cumulative &middot; ${money(running)}</span>
                    <span>${esc(days[days.length - 1].day)}</span>
                </div>
            </div>`;
    }

    function renderSpendByModel(s) {
        const rows = s.by_model || [];
        const el = document.getElementById('spendByModel');
        if (!rows.length) { el.innerHTML = ''; return; }
        el.innerHTML = `
            <h3 class="mb-8">By model</h3>
            <div class="card">
                <table class="render-table" style="width:100%;">
                    <tr><th>Model</th><th>Capability</th><th style="text-align:right;">Calls</th><th style="text-align:right;">Metered</th><th style="text-align:right;">Cost</th></tr>
                    ${rows.map(r => `<tr>
                        <td class="text-sm">${esc(r.model)}</td>
                        <td><span class="badge" style="background:${capColor(r.capability)}22;">${esc(r.capability)}</span></td>
                        <td style="text-align:right;">${r.calls}</td>
                        <td style="text-align:right;" class="text-sm text-muted">${qty(r.quantity)} ${esc(r.unit)}${r.quantity === 1 ? '' : 's'}</td>
                        <td style="text-align:right;">${money(r.usd)}</td>
                    </tr>`).join('')}
                </table>
            </div>`;
    }

    // Most expensive first. An average hides the shot that was regenerated
    // eleven times, which is the one worth knowing about.
    function renderSpendByShot(s) {
        const rows = (s.by_shot || []).slice(0, 25);
        const el = document.getElementById('spendByShot');
        if (!rows.length) { el.innerHTML = ''; return; }
        el.innerHTML = `
            <h3 class="mb-8">Most expensive shots</h3>
            <div class="card">
                <table class="render-table" style="width:100%;">
                    <tr><th>Shot</th><th>Scene</th><th style="text-align:right;">Calls</th><th style="text-align:right;">Cost</th><th style="text-align:right;">Per second</th></tr>
                    ${rows.map(r => {
                        const secs = (r.duration_ms || 0) / 1000;
                        return `<tr>
                            <td><a href="#" onclick="navigateTo('storyboard');return false;">${esc(r.shot_code || '(deleted shot)')}</a></td>
                            <td class="text-sm text-muted">${r.scene_number != null ? esc(String(r.scene_number)) : '—'}</td>
                            <td style="text-align:right;">${r.calls}</td>
                            <td style="text-align:right;">${money(r.usd)}</td>
                            <td style="text-align:right;" class="text-sm text-muted">${secs > 0 ? money(r.usd / secs) : '—'}</td>
                        </tr>`;
                    }).join('')}
                </table>
            </div>`;
    }


    // The subscription is the other currency.
    //
    // Nothing in the MCP path is billed per call — the agent host is the model,
    // on the user's own plan. But a director who runs out of Claude capacity
    // halfway through a breakdown is blocked exactly as hard as one who runs
    // out of Meshy credits; the resource is just denominated differently. So it
    // is shown beside the dollars rather than in a different screen.
    //
    // No bar until it is CALIBRATED. Anthropic publishes plan multipliers and
    // two windows, and no token count for any plan — a progress bar reading
    // "62% of your Max plan" against a number we invented would be believed and
    // planned around, which is worse than showing no bar at all.
    async function renderSubscription() {
        const el = document.getElementById('spendSubscription');
        try {
            const g = await api('/spend/subscription?project_id=' + state.currentProject.id);
            const win = w => {
                const bar = w.pct === null ? '' : `
                    <div style="background:var(--gl-border-subtle);border-radius:4px;height:6px;overflow:hidden;margin-top:6px;">
                        <div style="background:${w.pct > 90 ? 'var(--gl-error)' : w.pct > 70 ? 'var(--gl-warning)' : 'var(--gl-success)'};height:100%;width:${Math.min(100, w.pct)}%;border-radius:4px;"></div>
                    </div>`;
                return `<div>
                    <div class="text-sm text-muted">${esc(w.label)}</div>
                    <div style="font-size:20px;font-weight:600;">${qty(w.tokens)} tokens</div>
                    <div class="text-sm text-muted">${w.calls} tool call(s)${w.pct !== null ? ' &middot; ' + w.pct + '% of your window' : ''}</div>
                    ${bar}
                </div>`;
            };
            el.innerHTML = `
                <h3 class="mb-8">Subscription (MCP host)</h3>
                <div class="card">
                    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;">
                        ${win(g.windows.session)}${win(g.windows.week)}
                    </div>
                    ${g.by_tool && g.by_tool.length ? `
                        <details style="margin-top:12px;">
                            <summary class="text-sm text-muted" style="cursor:pointer;">where the tokens go — top tools</summary>
                            <table class="render-table" style="width:100%;margin-top:6px;">
                                ${g.by_tool.slice(0, 10).map(t => `<tr>
                                    <td class="text-sm">${esc(t.tool)}</td>
                                    <td class="text-sm text-muted" style="text-align:right;">${t.calls}×</td>
                                    <td class="text-sm" style="text-align:right;">${qty(t.tokens)} tokens</td>
                                </tr>`).join('')}
                            </table>
                        </details>` : ''}
                    ${g.allowance_tokens === null ? `
                        <p class="text-sm text-muted" style="margin-top:10px;border-top:1px solid var(--gl-border-subtle);padding-top:8px;">
                            No percentage shown because no ceiling is set. ${esc(g.note)}
                            Set <code>subscription_plan</code> and <code>subscription_pro_baseline_tokens</code> in Settings to calibrate it —
                            one measurement scales across plans via the published multipliers.
                        </p>` : `
                        <p class="text-sm text-muted" style="margin-top:10px;border-top:1px solid var(--gl-border-subtle);padding-top:8px;">
                            Calibrated to ${qty(g.allowance_tokens)} tokens per window${g.plan ? ' on ' + esc(g.plan) : ''}.
                            Counts are a floor — they cover the MCP payloads this server moved, not the host's own prompt and history.
                        </p>`}
                </div>`;
        } catch (err) { el.innerHTML = ''; }
    }


    // ── Compare generators ────────────────────────────────────────────────
    /*
     * WHICH GENERATOR SHOULD I USE.
     *
     * The rate book had the answer and no way to read it: one card per
     * provider, and the per-model table printed "1 image(s) per image" for
     * every row because the renderer used native_per_unit where the route was
     * already serving the price. Seven cards, no money, no ordering.
     *
     * This table exists to be READ ACROSS, so every row is priced for the same
     * unit of real work — a frame, a clip — and for a scene of them, since a
     * few cents per image is invisible until multiplied by a board. Cost sits
     * beside the tier's stated PURPOSE rather than replacing it: cheapest-wins
     * is the wrong read when draft models exist to be rolled repeatedly and
     * precision models exist to be right once.
     */
    let currentCompareCapability = 'image';

    async function loadGeneratorCompare(capability) {
        currentCompareCapability = capability || 'image';
        const el = document.getElementById('generatorCompare');
        if (!el) return;

        document.querySelectorAll('#compareCapTabs .tab-btn').forEach(b =>
            b.classList.toggle('active', b.dataset.cap === currentCompareCapability));
        const clipWrap = document.getElementById('compareClipWrap');
        if (clipWrap) clipWrap.style.display = currentCompareCapability === 'video' ? 'flex' : 'none';

        el.innerHTML = '<p class="text-sm text-muted">Reading the rate book…</p>';
        try {
            const params = ['capability=' + encodeURIComponent(currentCompareCapability)];
            // The project only supplies the delivery frame — the per-megapixel
            // providers cannot be priced without one, so a comparison with no
            // project is priced at a stated default rather than a hidden guess.
            if (state.currentProject) params.push('project_id=' + state.currentProject.id);
            if (currentCompareCapability === 'video') {
                const secs = parseInt(document.getElementById('compareClipSeconds')?.value, 10);
                if (secs > 0) params.push('clip_seconds=' + secs);
            }
            const r = await api('/spend/compare?' + params.join('&'));
            renderGeneratorCompare(r);
        } catch (err) {
            el.innerHTML = '<p class="text-sm">Could not read the rate book: ' + esc(err.message) + '</p>';
        }
    }

    /*
     * Precision follows magnitude, because the whole table is a comparison.
     * Two decimals rendered $0.011 and $0.015 as the same "$0.01" — the exact
     * distinction the cheapest two image models differ by, flattened away by
     * the formatter.
     */
    /*
     * THE FILM ESTIMATE. Counted from the project (subjects x their views, one
     * frame per shot, the footage's own length) and priced through the same
     * meters that bill a real generation, so changing the resolution or a
     * generator here shows exactly the difference it would make. The choices
     * live in PROD_EST and are sent as the query; the server owns every number.
     */
    const PROD_EST = { params: {} };

    async function loadProductionEstimate() {
        if (!state.currentProject) return;
        const out = document.getElementById('prodEstResult');
        if (!out) return;
        out.innerHTML = '<p class="text-sm text-muted">Counting and pricing…</p>';
        const q = Object.entries(PROD_EST.params).filter(([, v]) => v !== '' && v != null)
            .map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');
        try {
            const d = await api('/projects/' + state.currentProject.id + '/budget/production' + (q ? '?' + q : ''));
            PROD_EST.last = d;
            renderProductionEstimateControls(d);
            renderProductionEstimate(d);
        } catch (err) {
            out.innerHTML = '<p class="text-sm">Could not estimate: ' + esc(err.message) + '</p>';
        }
    }

    /** One choice changed: keep it and price again. */
    function prodEstSet(key, value) {
        if (key === 'image' || key === 'video' || key === 'upscale') {
            const [provider, model] = String(value || '').split('|');
            PROD_EST.params[key + '_provider'] = provider || '';
            PROD_EST.params[key + '_model'] = model || '';
        } else {
            PROD_EST.params[key] = value;
        }
        loadProductionEstimate();
    }

    function prodEstReset() {
        PROD_EST.params = {};
        loadProductionEstimate();
    }

    function renderProductionEstimateControls(d) {
        const el = document.getElementById('prodEstControls');
        if (!el) return;
        const g = d.generators || {};
        const optFor = cap => {
            const cur = g[cap] || {};
            const curKey = (cur.provider || '') + '|' + (cur.model || '');
            const rows = (d.alternatives && d.alternatives[cap]) || [];
            const seen = new Set();
            const opts = [];
            const add = (key, label) => { if (seen.has(key)) return; seen.add(key); opts.push(`<option value="${esc(key)}" ${key === curKey ? 'selected' : ''}>${esc(label)}</option>`); };
            add(curKey, `${cur.provider_label || cur.provider || 'none'} · ${cur.model || 'its default model'}`);
            for (const a of rows) add(a.provider + '|' + (a.model || ''), `${a.provider_label} · ${a.model || 'default'} — ${usd(a.usd)}`);
            return opts.join('');
        };
        const num = (key, label, val, help, step) => `<label class="text-sm" style="display:flex;flex-direction:column;gap:4px;">
            <span class="text-muted">${esc(label)}</span>
            <input type="number" min="0" step="${step || 1}" value="${esc(String(val))}" style="width:90px;" title="${esc(help || '')}"
                   onchange="prodEstSet('${key}', this.value)"></label>`;
        const c = d.counts || {};
        el.innerHTML = `<div class="card" style="display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end;">
            <label class="text-sm" style="display:flex;flex-direction:column;gap:4px;"><span class="text-muted">Resolution</span>
              <select onchange="prodEstSet('resolution', this.value)">${(d.resolutions || []).map(r =>
                `<option value="${esc(r.id)}" ${r.id === d.resolution.id ? 'selected' : ''}>${esc(r.label)}${d.project_resolution && r.id === d.resolution.id && !PROD_EST.params.resolution ? ' (project)' : ''}</option>`).join('')}</select></label>
            <label class="text-sm" style="display:flex;flex-direction:column;gap:4px;min-width:240px;"><span class="text-muted">Plates and storyboard</span>
              <select onchange="prodEstSet('image', this.value)">${optFor('image')}</select></label>
            <label class="text-sm" style="display:flex;flex-direction:column;gap:4px;min-width:240px;"><span class="text-muted">Footage</span>
              <select onchange="prodEstSet('video', this.value)">${optFor('video')}</select></label>
            <label class="text-sm" style="display:flex;flex-direction:column;gap:4px;min-width:240px;"><span class="text-muted">Upscale footage to ${esc(d.resolution.label)}</span>
              <select onchange="prodEstSet('upscale', this.value)"><option value="|">No upscale${d.upscale_needed ? ' (footage is made smaller)' : ''}</option>${((d.alternatives && d.alternatives.post) || []).map(a => {
                const key = a.provider + '|' + (a.model || '');
                const cur = !!a.current;
                return `<option value="${esc(key)}" ${cur ? 'selected' : ''}>${esc(a.provider_label)} · ${esc(a.model || 'default')} — ${usd(a.usd)}${a.needs_key ? ' (no key)' : ''}</option>`; }).join('')}</select></label>
            ${num('character_views', 'Views per character', c.views ? c.views.character : 4, 'front, two profiles, back')}
            ${num('location_views', 'Views per location', c.views ? c.views.location : 4)}
            ${num('prop_views', 'Views per prop', c.views ? c.views.prop : 1)}
            ${num('takes_plates', 'Attempts per plate', d.takes.plates, 'usually 3-4, sometimes 6', 0.5)}
            ${num('takes_storyboard', 'Attempts per frame', d.takes.storyboard, 'usually 3-4, sometimes 6', 0.5)}
            ${num('takes_footage', 'Attempts per clip', d.takes.footage, 'usually 2-3', 0.5)}
            ${c.shots ? '' : num('shot_seconds', 'Average shot (s)', c.shot_seconds)}
            ${num('runtime_seconds', 'Running time (s)', d.runtime ? Math.round(d.runtime.seconds) : 0, 'leave as measured, or type the length you expect')}
            <button class="btn btn-secondary" onclick="prodEstReset()">Back to the project's choices</button>
        </div>`;
    }

    function renderProductionEstimate(d) {
        const el = document.getElementById('prodEstResult');
        if (!el) return;
        const t = d.totals || {};
        const g = d.generators || {};
        const c = d.counts || {};
        const card = (label, v, sub) => `<div class="card" style="flex:1;min-width:160px;">
            <div class="text-sm text-muted">${esc(label)}</div>
            <div style="font-size:24px;font-weight:600;">${usd(v)}</div>
            <div class="text-sm text-muted">${sub}</div></div>`;
        const plates = (d.lines || []).filter(l => l.category === 'plates');
        const board = (d.lines || []).find(l => l.category === 'storyboard') || {};
        const foot = (d.lines || []).find(l => l.category === 'footage') || {};
        const plateCount = plates.reduce((n, l) => n + l.count, 0);
        const row = (what, n, size, model, unit, total) => `<tr><td>${what}</td><td>${n}</td><td>${esc(size || '')}</td>
            <td>${esc(model || '')}</td><td>${unit}</td><td style="text-align:right;">${usd(total)}</td></tr>`;
        const names = { character: 'Character plates', location: 'Location plates', prop: 'Prop plates' };
        const alt = cap => {
            const rows = ((d.alternatives || {})[cap] || []).slice(0, 14);
            if (!rows.length) return '<p class="text-sm text-muted">No other connected generator can price this.</p>';
            return '<table class="render-table" style="width:100%;"><tbody>' + rows.map(a => `<tr${a.current ? ' style="font-weight:600;"' : ''}>
                <td>${esc(a.provider_label)} · ${esc(a.model || 'default')}${a.current ? ' (selected)' : ''}${a.needs_key ? ' <span class="badge" title="No API key for this account yet: priced so you can compare, but it cannot run until one is added in Setup">no key</span>' : ''}${a.connected === false ? ` <span class="badge" title="${esc(a.not_connected_why || '')}">not connected</span>` : ''}${a.inferred ? ' <span class="badge" title="Worked out from the vendor plan prices, not a published per-item rate">estimated</span>' : ''}${a.delivers_less ? ` <span class="badge" style="background:var(--gl-warning);color:#111;" title="Cannot deliver ${esc(d.resolution.label)}">${cap === 'video' ? 'makes ' + esc(a.delivers_less) : 'smaller than asked'}</span>` : ''}</td>
                <td style="text-align:right;">${usd(a.usd)}</td><td style="text-align:right;white-space:nowrap;" class="text-muted">film ${usd(a.total)}</td>
                <td>${a.current || a.connected === false ? '' : `<button class="btn btn-secondary btn-sm" onclick="prodEstSet('${cap}', ${jsAttr(a.provider + '|' + (a.model || ''))})">Use</button>`}</td></tr>`).join('')
                + '</tbody></table>';
        };
        const rt = d.runtime;
        el.innerHTML = `
            <div style="display:flex;flex-wrap:wrap;gap:12px;" class="mb-16">
              ${card('The film', t.total, `${esc(d.resolution.label)} · ${c.frames} shots · ${Math.round(c.footage_seconds)}s of footage`
                  + (d.range ? `<br>${usd(d.range.low.total)} – ${usd(d.range.high.total)} at ${d.attempts.image.low}–${d.attempts.image.high} attempts per picture, ${d.attempts.footage.low}–${d.attempts.footage.high} per clip`
                  + `<br>first attempts only: ${usd(d.range.first_attempt.total)}` : ''))}
              ${card('Plates', t.plates, `${plateCount} pictures on ${esc(g.image && g.image.provider_label || '?')}`)}
              ${card('Storyboard', t.storyboard, `${board.count || 0} frames`)}
              ${d.upscale ? card('Upscale', t.upscale || 0, d.upscale.usd == null ? esc(d.upscale.why || 'not priced')
                  : `${Math.round(d.upscale.seconds)}s from ${esc(d.upscale.from)} to ${esc(d.upscale.to)} on ${esc(d.upscale.provider_label)}`) : ''}
              ${card('Footage', t.footage, `${Math.round(foot.seconds || 0)}s on ${esc(g.video && g.video.provider_label || '?')}${foot.per_second_usd ? ' · ' + usd(foot.per_second_usd) + '/s' : ''}`)}
            </div>
            <div class="card mb-16"><table class="render-table" style="width:100%;">
              <thead><tr><th>What</th><th>Count</th><th>Size</th><th>Model</th><th>Each</th><th style="text-align:right;">Cost</th></tr></thead>
              <tbody>
                ${plates.map(l => row(`${names[l.kind]} <span class="text-muted">(${l.subjects} × ${l.views} view${l.views === 1 ? '' : 's'}${l.takes !== 1 ? ' × ' + l.takes + ' attempts' : ''})</span>`,
                    l.count, l.size, l.model, l.unit_usd == null ? esc(l.why || 'not priced') : usd(l.unit_usd), l.usd)).join('')}
                ${row(`Storyboard frames${board.takes !== 1 ? ` <span class="text-muted">(× ${board.takes} attempts)</span>` : ''}`, board.count || 0, board.size, board.model,
                    board.unit_usd == null ? esc(board.why || 'not priced') : usd(board.unit_usd), board.usd)}
                ${row(`Footage <span class="text-muted">(${Math.round(foot.seconds || 0)}s${foot.takes !== 1 ? ' × ' + foot.takes + ' attempts' : ''})</span>`, foot.count || 0,
                    foot.downgraded ? foot.delivered + ' (asked ' + foot.size + ')' : (foot.resolution_tier || foot.size), foot.model, foot.per_second_usd ? usd(foot.per_second_usd) + '/s' : '', foot.usd)}
                ${d.upscale && d.upscale.usd != null ? row('Upscale <span class="text-muted">(once)</span>', foot.count || 0,
                    d.upscale.from + ' → ' + d.upscale.to, d.upscale.model, '', d.upscale.usd) : ''}
              </tbody></table></div>
            <p class="text-sm text-muted mb-16">Running time: ${rt ? Math.round(rt.seconds) + 's, from ' + esc(rt.source)
                + (rt.range ? ` (likely; ${rt.range[0]}–${rt.range[1]}s)` : '') : 'unknown'}. Shots: ${esc(c.shot_source || '')}.</p>
            <div style="display:flex;flex-wrap:wrap;gap:16px;" class="mb-16">
              <div class="card" style="flex:1;min-width:300px;"><h3 class="mb-8">Plates and storyboard on other generators</h3>${alt('image')}</div>
              <div class="card" style="flex:1;min-width:300px;"><h3 class="mb-8">Footage on other generators</h3>${alt('video')}</div>
            </div>
            ${(d.notes || []).map(n => `<p class="text-sm text-muted">${esc(n)}</p>`).join('')}`;
    }

    function renderGeneratorCompare(r) {
        const el = document.getElementById('generatorCompare');
        const cheapest = r.rows.find(x => x.available && !x.self_hosted);

        const rows = r.rows.map(x => {
            const dim = x.available ? '' : 'opacity:.55;';
            return `<tr style="${dim}">
                <td class="text-sm">
                    <strong>${esc(x.provider_label)}</strong>
                    <div class="text-sm text-muted">${esc(x.model)}</div>
                </td>
                <td class="text-sm">
                    ${x.tier ? `<span class="badge" title="${esc(x.tier.why || '')}">${esc(x.tier.label)}</span>` : ''}
                    ${x.honours_resolution === false
                        ? `<span class="badge" style="background:var(--gl-warning);"
                                 title="${esc(x.size_note || '')}">ignores your resolution</span>` : ''}
                    ${x.max_size
                        ? `<span class="badge" title="The largest output this MODEL offers — not the provider's best"
                           >max ${esc(x.max_size)}</span>` : ''}
                    ${x.inferred ? '<span class="badge" title="Not published by the provider — inferred, and may be wrong">inferred</span>' : ''}
                    ${x.self_hosted ? '<span class="badge" title="No per-call charge. Zero because nobody bills for it, not because it is cheap.">self-hosted</span>' : ''}
                    ${x.available ? '' : `<span class="badge" style="background:var(--gl-warning);" title="${esc(x.needs || '')}">${x.connected === false ? 'not connected' : 'no key'}</span>`}
                </td>
                <td class="text-sm text-muted" style="text-align:right;white-space:nowrap;">
                    ${usd(x.usd_per_unit)}<span class="text-muted">/${esc(x.unit)}</span>
                    ${x.units_per_work !== 1
                        ? `<div class="text-sm text-muted">&times; ${x.units_per_work.toFixed(2)}</div>` : ''}
                </td>
                <td class="text-sm" style="text-align:right;white-space:nowrap;">
                    <strong>${usd(x.usd_per_work)}</strong>
                    ${cheapest && x === cheapest ? ' <span class="badge">cheapest</span>' : ''}
                </td>
                <td class="text-sm text-muted" style="text-align:right;white-space:nowrap;">${usd(x.usd_per_scene)}</td>
                <td class="text-sm text-muted" style="text-align:right;white-space:nowrap;">
                    ${x.source ? `<a href="${esc(x.source)}" target="_blank" rel="noopener">source</a>` : ''}
                    <div class="text-sm text-muted">${esc(x.checked || '')}${
                        x.checked_age_days !== null && x.checked_age_days > 90
                            ? ' <span class="badge" style="background:var(--gl-warning);" title="Nobody has re-verified this rate in over 90 days">stale</span>' : ''}</div>
                </td>
            </tr>`;
        }).join('');

        el.innerHTML = `
            <div class="card">
                <table class="render-table" style="width:100%;">
                    <thead><tr>
                        <th class="text-sm" style="text-align:left;">Generator</th>
                        <th class="text-sm" style="text-align:left;">For</th>
                        <th class="text-sm" style="text-align:right;">Rate</th>
                        <th class="text-sm" style="text-align:right;">${esc(r.work.work_label)}</th>
                        <th class="text-sm" style="text-align:right;">${esc(r.work.scene_label)}</th>
                        <th class="text-sm" style="text-align:right;">Checked</th>
                    </tr></thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
            ${r.unpriced && r.unpriced.length ? `
                <div class="card mb-8" style="border-color:var(--gl-warning);">
                    <strong class="text-sm">Not priced</strong>
                    ${r.unpriced.map(u => `<p class="text-sm">${esc(u.provider)} — ${esc(u.why)}</p>`).join('')}
                </div>` : ''}
            <p class="text-sm text-muted" style="margin-top:8px;">${esc(r.note)}</p>
            <p class="text-sm text-muted">A tier badge says what a model is FOR. Cheapest is not
               best: a draft model is meant to be rolled repeatedly, a precision one to be right once.</p>
            <p class="text-sm text-muted">&ldquo;Ignores your resolution&rdquo; means the provider has no
               width or height field &mdash; a requested size can only become an aspect ratio and the
               provider picks the pixels. Your project&rsquo;s delivery size reaches it in name only, and
               that applies to storyboard frames as much as to plates.</p>`;
    }

    // ── Rates ─────────────────────────────────────────────────────────────

    async function loadSpendRates() {
        try {
            const r = await api('/spend/rates');
            const el = document.getElementById('spendRates');
            el.innerHTML = r.rates.map(rate => `
                <div class="card mb-8">
                    <div class="flex-between">
                        <div>
                            <strong>${esc(rate.provider)}</strong>
                            <span class="badge" style="background:${capColor(rate.capability)}22;margin-left:6px;">${esc(rate.capability)}</span>
                            ${rate.self_hosted ? '<span class="badge" style="margin-left:6px;">self-hosted &middot; no per-call charge</span>' : ''}
                            ${rate.overridden ? '<span class="badge" style="margin-left:6px;background:var(--gl-warning);">overridden</span>' : ''}
                        </div>
                        <div class="text-sm text-muted">checked ${esc(rate.checked)}</div>
                    </div>
                    <p class="text-sm" style="margin:6px 0;">
                        Metered per <strong>${esc(rate.unit)}</strong>${rate.native_unit !== rate.unit
                            ? ` &middot; billed as <strong>${qty(rate.native_per_unit)} ${esc(rate.native_unit)}(s)</strong> per ${esc(rate.unit)}` : ''}
                        ${rate.components
                            ? ` &middot; $${(rate.components.input * 1e6).toFixed(2)}/M in, $${(rate.components.output * 1e6).toFixed(2)}/M out`
                            : ` &middot; ${'$' + (rate.usd_per_unit || 0).toFixed(6).replace(/0+$/, '').replace(/\.$/, '')} per ${esc(rate.unit)}`}
                    </p>
                    ${rate.note ? `<p class="text-sm text-muted">${esc(rate.note)}</p>` : ''}
                    ${rate.models && rate.models.length ? `
                        <details style="margin-top:6px;">
                            <summary class="text-sm text-muted" style="cursor:pointer;">${rate.models.length} model rate(s)</summary>
                            <table class="render-table" style="width:100%;margin-top:6px;">
                                ${rate.models.map(m => `<tr>
                                    <td class="text-sm">${esc(m.model)}${m.inferred ? ' <span class="badge">inferred</span>' : ''}</td>
                                    <td class="text-sm text-muted" style="text-align:right;">${m.components
                                        ? `$${(m.components.input * 1e6).toFixed(2)}/M in &middot; $${(m.components.output * 1e6).toFixed(2)}/M out`
                                        : /*
                                           * THE PRICE, not the conversion factor.
                                           * This printed `${qty(m.native_per_unit)} ${native_unit}(s) per ${unit}`
                                           * — "1 image(s) per image" for every row — while the route
                                           * was already serving usd_per_native. The one table that
                                           * could compare models showed no money at all.
                                           */
                                          `$${Number(m.usd_per_native ?? 0).toFixed(4).replace(/0+$/, '').replace(/\.$/, '')} per ${esc(rate.unit)}`}</td>
                                </tr>`).join('')}
                            </table>
                        </details>` : ''}
                    <p class="text-sm text-muted" style="margin-top:6px;">
                        <a href="${esc(rate.source)}" target="_blank" rel="noopener">source</a>
                    </p>
                </div>`).join('');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // ══════════════════════════════════════════════════════════════
    // FILM-164: BUDGET DASHBOARD
    // ══════════════════════════════════════════════════════════════
    async function loadBudget() {
        if (!state.currentProject) return;
        setStatus('Loading budget...');
        try {
            const [summary, ledger, forecast] = await Promise.all([
                api('/projects/' + state.currentProject.id + '/budget'),
                api('/projects/' + state.currentProject.id + '/budget/ledger?limit=50'),
                api('/projects/' + state.currentProject.id + '/budget/forecast'),
            ]);

            // Summary cards
            const total = summary.total_spent || 0;
            const limit = summary.budget_total || 0;
            const pct = limit > 0 ? Math.min(100, (total / limit * 100)).toFixed(1) : 0;
            const barColor = pct > 90 ? 'var(--gl-error)' : pct > 70 ? 'var(--gl-warning)' : 'var(--gl-success)';

            document.getElementById('budgetSummary').innerHTML = `
                <div class="card">
                    <div class="flex-between mb-8">
                        <div>
                            <span class="text-sm text-muted">Total Spent</span>
                            <h2 style="font-size:24px;">$${total.toFixed(2)}</h2>
                        </div>
                        <div style="text-align:right;">
                            <span class="text-sm text-muted">Budget Limit</span>
                            <h2 style="font-size:24px;">${limit > 0 ? '$' + limit.toFixed(2) : 'Not set'}</h2>
                        </div>
                    </div>
                    ${limit > 0 ? `
                        <div style="background:var(--gl-border-subtle);border-radius:4px;height:8px;overflow:hidden;">
                            <div style="background:${barColor};height:100%;width:${pct}%;transition:width 0.3s;border-radius:4px;"></div>
                        </div>
                        <p class="text-sm text-muted" style="margin-top:4px;">${pct}% used</p>
                    ` : ''}
                    ${forecast.avg_daily_spend ? `<p class="text-sm" style="margin-top:8px;">Avg daily: $${forecast.avg_daily_spend.toFixed(2)}${forecast.days_until_exhausted ? ' &middot; ~' + forecast.days_until_exhausted + ' days remaining' : ''}</p>` : ''}
                </div>`;

            // Breakdown by type (inline SVG bar chart)
            const breakdown = summary.breakdown || [];
            if (breakdown.length > 0) {
                const maxAmt = Math.max(...breakdown.map(b => b.amount));
                const typeColors = { render_gpu: '#e91e63', image_generation: '#2196f3', video_generation: '#9c27b0', voice_synthesis: '#ff9800', music_generation: '#4caf50', api_call: '#00bcd4', storage: '#607d8b', license: '#795548', other: '#9e9e9e' };
                document.getElementById('budgetBreakdown').innerHTML = `
                    <h3 class="mb-8">Cost Breakdown</h3>
                    <div class="card">
                        ${breakdown.map(b => `
                            <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
                                <span class="text-sm" style="width:120px;flex-shrink:0;">${esc(b.cost_type.replace(/_/g, ' '))}</span>
                                <div style="flex:1;background:var(--gl-border-subtle);border-radius:3px;height:16px;overflow:hidden;">
                                    <div style="background:${typeColors[b.cost_type] || '#9e9e9e'};height:100%;width:${maxAmt > 0 ? (b.amount / maxAmt * 100) : 0}%;border-radius:3px;"></div>
                                </div>
                                <span class="text-sm" style="width:80px;text-align:right;">$${b.amount.toFixed(2)}</span>
                                <span class="text-sm text-muted" style="width:40px;text-align:right;">${b.count}x</span>
                            </div>
                        `).join('')}
                    </div>`;
            } else {
                document.getElementById('budgetBreakdown').innerHTML = '';
            }

            // Ledger table
            const entries = ledger.entries || [];
            if (entries.length === 0) {
                document.getElementById('budgetLedger').innerHTML = '<p class="text-sm text-muted">No cost entries yet.</p>';
            } else {
                document.getElementById('budgetLedger').innerHTML = `
                    <table class="render-table">
                        <tr><th>Type</th><th>Amount</th><th>Description</th><th>Model</th><th>Date</th><th></th></tr>
                        ${entries.map(e => `<tr>
                            <td><span class="badge">${esc(e.cost_type)}</span></td>
                            <td>$${(e.amount || 0).toFixed(2)}</td>
                            <td class="text-sm">${esc(e.description || '-')}</td>
                            <td class="text-sm text-muted">${esc(e.model_used || '-')}</td>
                            <td class="text-sm text-muted">${new Date(e.created_at).toLocaleDateString()}</td>
                            <td><button class="btn btn-danger btn-sm" onclick="deleteCostEntry('${e.id}')" style="padding:2px 6px;font-size:10px;">x</button></td>
                        </tr>`).join('')}
                    </table>`;
            }
            setStatus('Budget loaded');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function saveCostEntry() {
        if (!state.currentProject) return;
        const data = getModalData('costEntryModal');
        data.amount = parseFloat(data.amount) || 0;
        data.gpu_seconds = parseInt(data.gpu_seconds) || 0;
        try {
            await api('/projects/' + state.currentProject.id + '/budget', { method: 'POST', body: JSON.stringify(data) });
            closeModal('costEntryModal');
            loadBudget();
            setStatus('Cost entry added');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteCostEntry(entryId) {
        if (!confirm('Delete this cost entry?')) return;
        try {
            await api('/budget/' + entryId, { method: 'DELETE' });
            loadBudget();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function saveBudgetLimit() {
        if (!state.currentProject) return;
        const data = getModalData('budgetLimitModal');
        try {
            /*
             * An unset currency is omitted rather than sent empty. The route
             * takes both, and "" would be stored as a currency of nothing —
             * the same two-states-spelled-alike bug that once dropped a
             * project's image and video provider on every save.
             */
            const limitBody = { budget_total: parseFloat(data.budget_limit) || 0 };
            if (data.budget_currency) limitBody.budget_currency = data.budget_currency;
            await api('/projects/' + state.currentProject.id + '/budget/limit',
                { method: 'PUT', body: JSON.stringify(limitBody) });
            closeModal('budgetLimitModal');
            loadBudget();
            setStatus('Budget limit updated');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // ══════════════════════════════════════════════════════════════
    // FILM-165: BUDGET ESTIMATION
    // ══════════════════════════════════════════════════════════════
    let currentBudgetEstimate = null;

    // Panels are derived from the tab buttons rather than listed here, so a tab
    // added later cannot end up with nothing to show — which is exactly how the
    // previous two-tab version would have failed the moment a third arrived.
    const BUDGET_PANELS = { spend: 'budgetTabSpend', film: 'budgetTabFilm', tracking: 'budgetTabTracking',
                            compare: 'budgetTabCompare',
                            rates: 'budgetTabRates', estimation: 'budgetTabEstimation' };

    function switchBudgetTab(tab) {
        document.querySelectorAll('#budgetTabs .tab-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.tab === tab);
        });
        for (const [name, id] of Object.entries(BUDGET_PANELS)) {
            const el = document.getElementById(id);
            if (el) el.style.display = name === tab ? 'block' : 'none';
        }
        if (tab === 'spend') loadSpend();
        if (tab === 'rates') loadSpendRates();
        if (tab === 'compare') loadGeneratorCompare(currentCompareCapability);
        if (tab === 'film') loadProductionEstimate();
        if (tab === 'estimation' && !currentBudgetEstimate) generateBudgetEstimate();
    }

    async function generateBudgetEstimate() {
        if (!state.currentProject) return;
        const template = document.getElementById('budgetTemplateSelect').value;
        setStatus('Generating budget estimate...');
        try {
            const estimate = await api('/projects/' + state.currentProject.id + '/budget/estimate?template=' + template + '&refresh=true');
            currentBudgetEstimate = estimate;
            renderBudgetEstimate(estimate);
            setStatus('Budget estimate generated');
        } catch (err) {
            setStatus('Error: ' + err.message);
            document.getElementById('budgetAnalysisSummary').innerHTML = '<p class="text-muted">Failed to generate estimate. Make sure you have scenes and shots created.</p>';
        }
    }

    function renderBudgetEstimate(estimate) {
        // Project Analysis Summary
        const stats = estimate.stats || {};
        document.getElementById('budgetAnalysisSummary').innerHTML = `
            <div class="card">
                <h3 class="mb-8">Project Analysis</h3>
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:16px;">
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-brand-pink);">${stats.scene_count || 0}</div>
                        <div class="text-sm text-muted">Scenes</div>
                    </div>
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-brand-blue);">${stats.shot_count || 0}</div>
                        <div class="text-sm text-muted">Shots</div>
                    </div>
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-accent-purple);">${stats.character_count || 0}</div>
                        <div class="text-sm text-muted">Characters</div>
                    </div>
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-success);">${stats.location_count || 0}</div>
                        <div class="text-sm text-muted">Locations</div>
                    </div>
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-warning);">${stats.shooting_days_estimate || '?'}</div>
                        <div class="text-sm text-muted">Est. Shoot Days</div>
                    </div>
                    <div class="text-center">
                        <div class="text-2xl" style="color:var(--gl-info);">${stats.complexity_score || 0}</div>
                        <div class="text-sm text-muted">Complexity</div>
                    </div>
                </div>
            </div>`;

        // Missing Data Cards
        const missingData = estimate.missing_data || [];
        if (missingData.length > 0) {
            document.getElementById('budgetMissingData').innerHTML = `
                <div class="card" style="border-color:var(--gl-warning);background:rgba(245,158,11,0.05);">
                    <div class="flex-between mb-8">
                        <h3 style="color:var(--gl-warning);">Missing Cost Data (${missingData.length})</h3>
                        <span class="badge badge-warning">Estimates may be inaccurate</span>
                    </div>
                    <p class="text-sm text-muted mb-8">The following items need cost information for accurate budgeting. Click to enter values.</p>
                    <div style="display:flex;flex-wrap:wrap;gap:8px;">
                        ${missingData.slice(0, 10).map(item => `
                            <button class="btn btn-secondary btn-sm" onclick="showCostInputModal('${item.entity_type}', '${item.entity_id}', '${esc(item.entity_name)}')">
                                ${item.entity_type === 'character' ? '👤' : '📍'} ${esc(item.entity_name)}
                                <span class="text-muted" style="margin-left:4px;">$${item.suggested_range ? (item.suggested_range.min + '-' + item.suggested_range.max) : '?'}</span>
                            </button>
                        `).join('')}
                        ${missingData.length > 10 ? `<span class="text-muted text-sm">+${missingData.length - 10} more</span>` : ''}
                    </div>
                </div>`;
        } else {
            document.getElementById('budgetMissingData').innerHTML = '';
        }

        // Budget Breakdown by Category
        const lineItems = estimate.line_items || [];
        const categories = {
            above_the_line: { label: 'Above the Line', items: [], total: 0 },
            below_the_line_production: { label: 'Below the Line (Production)', items: [], total: 0 },
            post_production: { label: 'Post-Production', items: [], total: 0 },
            other: { label: 'Other', items: [], total: 0 }
        };

        for (const item of lineItems) {
            const cat = categories[item.category] || categories.other;
            cat.items.push(item);
            cat.total += item.amount || 0;
        }

        const confidenceColors = { high: 'var(--gl-success)', medium: 'var(--gl-warning)', low: 'var(--gl-error)' };
        const sourceIcons = { manual: '✏️', estimated: '📊', calculated: '🔢', web_search: '🔍', ai_estimate: '🤖' };

        document.getElementById('budgetEstimateBreakdown').innerHTML = `
            <div class="card mb-16">
                <div class="flex-between mb-16">
                    <h2>Total Estimated Budget</h2>
                    <div class="text-right">
                        <div class="text-3xl" style="color:var(--gl-brand-pink);">$${(estimate.total_estimated || 0).toLocaleString()}</div>
                        <div class="text-sm text-muted">${estimate.template_label || estimate.template}</div>
                    </div>
                </div>
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;padding-top:16px;border-top:1px solid var(--gl-border-subtle);">
                    <div>
                        <div class="text-sm text-muted">Above the Line</div>
                        <div class="text-lg">$${(estimate.above_the_line || 0).toLocaleString()}</div>
                    </div>
                    <div>
                        <div class="text-sm text-muted">Below the Line</div>
                        <div class="text-lg">$${(estimate.below_the_line || 0).toLocaleString()}</div>
                    </div>
                    <div>
                        <div class="text-sm text-muted">Post-Production</div>
                        <div class="text-lg">$${(estimate.post_production || 0).toLocaleString()}</div>
                    </div>
                    <div>
                        <div class="text-sm text-muted">Other + Contingency</div>
                        <div class="text-lg">$${(estimate.other_costs || 0).toLocaleString()}</div>
                    </div>
                </div>
            </div>

            ${Object.entries(categories).filter(([k, v]) => v.items.length > 0).map(([key, cat]) => `
                <div class="card mb-8">
                    <details open>
                        <summary style="cursor:pointer;user-select:none;" class="flex-between">
                            <h3>${cat.label}</h3>
                            <span class="text-lg">$${cat.total.toLocaleString()}</span>
                        </summary>
                        <table class="entity-table" style="margin-top:12px;">
                            <thead>
                                <tr><th>Item</th><th>Description</th><th style="text-align:right;">Amount</th><th>Source</th></tr>
                            </thead>
                            <tbody>
                                ${cat.items.map(item => `
                                    <tr>
                                        <td>${esc(item.subcategory.replace(/_/g, ' '))}</td>
                                        <td class="text-muted text-sm">${esc(item.description || '')}</td>
                                        <td style="text-align:right;">$${(item.amount || 0).toLocaleString()}</td>
                                        <td>
                                            <span title="${item.source}" style="color:${confidenceColors[item.confidence] || confidenceColors.low};">
                                                ${sourceIcons[item.source] || ''}
                                            </span>
                                        </td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                    </details>
                </div>
            `).join('')}

            ${(estimate.assumptions || []).length > 0 ? `
                <div class="card">
                    <h3 class="mb-8">Assumptions</h3>
                    <ul class="text-sm text-muted" style="margin:0;padding-left:20px;">
                        ${estimate.assumptions.map(a => `<li>${esc(a)}</li>`).join('')}
                    </ul>
                </div>
            ` : ''}
        `;
    }

    function showCostInputModal(entityType, entityId, entityName) {
        const html = `
            <div class="modal-header">
                <h3>Set Cost: ${esc(entityName)}</h3>
                <button class="modal-close" onclick="closeModal('costInputModal')">&times;</button>
            </div>
            <div class="modal-body">
                ${entityType === 'character' ? `
                    <div class="form-group">
                        <label>Talent Tier</label>
                        <select id="costInputTier" data-field="talent_tier">
                            <option value="unknown">Unknown</option>
                            <option value="background">Background / Extra ($150-300/day)</option>
                            <option value="day_player">Day Player ($1K-3K/day)</option>
                            <option value="supporting">Supporting ($5K-25K/week)</option>
                            <option value="lead">Lead ($25K-100K/project)</option>
                            <option value="star">Star ($100K-500K/project)</option>
                            <option value="a_list">A-List ($500K-20M/project)</option>
                        </select>
                    </div>
                    <div class="form-group">
                        <label>Day Rate ($)</label>
                        <input type="number" id="costInputDayRate" data-field="day_rate" min="0" step="100" placeholder="e.g., 5000">
                    </div>
                    <div class="form-group">
                        <label>Shooting Days</label>
                        <input type="number" id="costInputShootingDays" data-field="shooting_days" min="1" placeholder="e.g., 10">
                    </div>
                    <div class="form-group">
                        <label>Actor Name (optional)</label>
                        <input type="text" id="costInputActorName" data-field="actor_name" placeholder="e.g., Tom Hanks">
                    </div>
                    <div class="form-group">
                        <label>Travel Allowance ($)</label>
                        <input type="number" id="costInputTravel" data-field="travel_allowance" min="0" step="50"
                               placeholder="e.g., 1200">
                        <span class="text-sm text-muted">Flights, hotel and per diem for the whole engagement — not per day.</span>
                    </div>
                ` : `
                    <div class="form-group">
                        <label>Location Type</label>
                        <select id="costInputLocType" data-field="location_type">
                            <option value="unknown">Unknown</option>
                            <option value="practical">Practical Location ($500-5K/day)</option>
                            <option value="studio">Studio / Stage ($2K-25K/day)</option>
                            <option value="backlot">Backlot ($1K-10K/day)</option>
                            <option value="remote">Remote Location ($3K-15K/day)</option>
                            <option value="international">International ($5K-50K/day)</option>
                        </select>
                    </div>
                    <div class="form-group">
                        <label>Daily Rate ($)</label>
                        <input type="number" id="costInputDailyRate" data-field="daily_rate" min="0" step="100" placeholder="e.g., 2500">
                    </div>
                    <div class="form-group">
                        <label>Shoot Days</label>
                        <input type="number" id="costInputShootDays" data-field="shoot_days" min="1" placeholder="e.g., 3">
                    </div>
                    <div class="form-group">
                        <label>Prep Days</label>
                        <input type="number" id="costInputPrepDays" data-field="prep_days" min="0" placeholder="e.g., 1">
                        <span class="text-sm text-muted">Days held before the shoot — dressing, rigging, a tech scout. Billed at the same daily rate.</span>
                    </div>
                    <div class="form-group">
                        <label>Permits Cost ($)</label>
                        <input type="number" id="costInputPermits" data-field="permits_cost" min="0" step="50" placeholder="e.g., 500">
                    </div>
                `}
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('costInputModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveCostInput('${entityType}', '${entityId}')">Save</button>
            </div>
        `;

        // Create or reuse modal
        let modal = document.getElementById('costInputModal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'costInputModal';
            modal.className = 'modal-overlay';
            modal.innerHTML = '<div class="modal">' + html + '</div>';
            document.body.appendChild(modal);
        } else {
            modal.querySelector('.modal').innerHTML = html;
        }
        // Same fault: this form never appeared at all, which is why nobody
        // noticed it was missing its travel allowance and prep days.
        showModal(modal.id);
    }

    async function saveCostInput(entityType, entityId) {
        const data = {};
        document.querySelectorAll('#costInputModal [data-field]').forEach(el => {
            const field = el.dataset.field;
            const val = el.value;
            if (val) {
                if (['day_rate', 'daily_rate', 'permits_cost', 'travel_allowance'].includes(field)) {
                    data[field] = parseFloat(val);
                } else if (['shooting_days', 'shoot_days', 'prep_days'].includes(field)) {
                    data[field] = parseInt(val);
                } else {
                    data[field] = val;
                }
            }
        });

        if (Object.keys(data).length === 0) {
            setStatus('Please enter at least one value');
            return;
        }

        try {
            await api('/' + entityType + 's/' + entityId + '/cost', { method: 'PUT', body: JSON.stringify(data) });
            closeModal('costInputModal');
            setStatus('Cost data saved');
            generateBudgetEstimate();
        } catch (err) {
            setStatus('Error: ' + err.message);
        }
    }

    function exportBudgetEstimate() {
        if (!currentBudgetEstimate) {
            setStatus('No estimate to export');
            return;
        }

        const lines = [
            ['Category', 'Subcategory', 'Description', 'Amount', 'Source', 'Confidence'],
            ...currentBudgetEstimate.line_items.map(item => [
                item.category,
                item.subcategory,
                item.description || '',
                item.amount || 0,
                item.source || '',
                item.confidence || ''
            ])
        ];

        lines.push([]);
        lines.push(['TOTAL', '', '', currentBudgetEstimate.total_estimated]);
        lines.push([]);
        lines.push(['Template', currentBudgetEstimate.template]);
        lines.push(['Generated', new Date().toISOString()]);

        const csv = lines.map(row => row.map(cell => '"' + String(cell).replace(/"/g, '""') + '"').join(',')).join('\n');
        const blob = new Blob([csv], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = (state.currentProject?.title || 'budget') + '_estimate.csv';
        a.click();
        URL.revokeObjectURL(url);
        setStatus('Budget estimate exported');
    }
